'use strict';

const test = require('tape');
const EventTarget = require('../lib/eventtarget');

test('create the peer connections', function(t) {
  t.plan(1);

  let emitter = new EventTarget();

  function next() {
  }

  function removeNext() {
    emitter.removeEventListener('foo', next);
  }

  emitter.addEventListener('foo', removeNext);
  emitter.addEventListener('foo', next);

  emitter.addEventListener('foo', () => {
    t.ok(true, 'invokes next foo');
  });

  emitter.dispatchEvent({ type: 'foo' });
});
